/**
 * Sky catalog: naked-eye stars, all 88 IAU constellation figures and the
 * Milky Way band - GENERATED DATA, do not hand-edit.
 *
 * Stars: 5044 entries down to visual magnitude 6.0 (the naked-eye limit) with
 * B-V colour indices, from the Yale Bright Star Catalogue / HYG database.
 * Figures: the 88 IAU constellations (Serpens in its two traditional parts)
 * with J2000 line vertices and label positions. Milky Way: 3361 points sampled
 * from the real five-level brightness contours of the galactic band, so the
 * glow sits where the Milky Way actually is - the soft rendering itself is
 * stylised, the positions are not.
 *
 * Source: d3-celestial (https://github.com/ofrohn/d3-celestial),
 * Copyright (c) 2015 Olaf Frohn, BSD-3-Clause. Full notice in SOURCES.md.
 * Coordinates are J2000 equatorial, quantised to 0.01 deg.
 */

function dec36(s: string, at: number, w: number): number {
  return parseInt(s.slice(at, at + w), 36);
}

/** Decode a run of 8-char (ra, dec) pairs into a flat degree array. */
export function decodePoints(blob: string): Float32Array {
  const n = blob.length / 8;
  const out = new Float32Array(n * 2);
  for (let i = 0; i < n; i++) {
    out[i * 2] = dec36(blob, i * 8, 4) / 100;
    out[i * 2 + 1] = dec36(blob, i * 8 + 4, 4) / 100 - 90;
  }
  return out;
}

/** Effective temperature from a B-V colour index (Ballesteros 2012). */
export function bvToTempK(bv: number): number {
  const b = Math.max(-0.35, Math.min(2.2, bv));
  return 4600 * (1 / (0.92 * b + 1.7) + 1 / (0.92 * b + 0.62));
}

/** Approximate sRGB of a blackbody at temperature K (Planckian locus fit). */
export function tempToRGB(kelvin: number): [number, number, number] {
  const t = Math.max(1800, Math.min(30000, kelvin)) / 100;
  let r: number, g: number, b: number;
  if (t <= 66) {
    r = 255;
    g = Math.max(0, Math.min(255, 99.47 * Math.log(t) - 161.12));
    b = t <= 19 ? 0 : Math.max(0, Math.min(255, 138.52 * Math.log(t - 10) - 305.04));
  } else {
    r = Math.max(0, Math.min(255, 329.7 * Math.pow(t - 60, -0.1332)));
    g = Math.max(0, Math.min(255, 288.12 * Math.pow(t - 60, -0.0755)));
    b = 255;
  }
  return [r | 0, g | 0, b | 0];
}

export function tempToCss(kelvin: number, alpha = 1): string {
  const [r, g, b] = tempToRGB(kelvin);
  return alpha >= 1 ? `rgb(${r},${g},${b})` : `rgba(${r},${g},${b},${alpha})`;
}

/* ------------------------------------------------------------- stars --- */

const STAR_BLOB =
  '';

export const STAR_COUNT = STAR_BLOB.length / 12;
export const STAR_RA = new Float32Array(STAR_COUNT);
export const STAR_DEC = new Float32Array(STAR_COUNT);
export const STAR_MAG = new Float32Array(STAR_COUNT);
export const STAR_TEMP = new Float32Array(STAR_COUNT);

for (let i = 0; i < STAR_COUNT; i++) {
  const at = i * 12;
  STAR_RA[i] = dec36(STAR_BLOB, at, 4) / 100;
  STAR_DEC[i] = dec36(STAR_BLOB, at + 4, 4) / 100 - 90;
  STAR_MAG[i] = dec36(STAR_BLOB, at + 8, 2) / 20 - 2;
  STAR_TEMP[i] = bvToTempK(dec36(STAR_BLOB, at + 10, 2) / 50 - 0.6);
}

