/* ----------------------------------------------------- constellations --- */

export interface ConstellationFigure {
  /** IAU three-letter abbreviation, e.g. "Ori". */
  id: string;
  name: string;
  /** Polylines of the stick figure, each a flat [ra, dec, ...] degree array. */
  segments: Float32Array[];
  /** Label anchor. */
  labelRa: number;
  labelDec: number;
  /** 1 = most prominent, 3 = faint - used to thin labels out. */
  rank: number;
}

interface RawFigure { id: string; name: string; label: string; rank: number; lines: string }

