export const FIGURES: ConstellationFigure[] = RAW_FIGURES.map((f) => {
  const label = decodePoints(f.label);
  return {
    id: f.id,
    name: f.name,
    segments: f.lines.split(';').map(decodePoints),
    labelRa: label[0],
    labelDec: label[1],
    rank: f.rank,
  };
});

/* --------------------------------------------------------- milky way --- */

const MW_BLOB =
  '';

/** Sampled band points: [ra, dec, brightness 1-5] per entry. */
export const MILKY_WAY_COUNT = MW_BLOB.length / 9;
export const MILKY_WAY = new Float32Array(MILKY_WAY_COUNT * 3);
for (let i = 0; i < MILKY_WAY_COUNT; i++) {
  const at = i * 9;
  MILKY_WAY[i * 3] = dec36(MW_BLOB, at, 4) / 100;
  MILKY_WAY[i * 3 + 1] = dec36(MW_BLOB, at + 4, 4) / 100 - 90;
  MILKY_WAY[i * 3 + 2] = dec36(MW_BLOB, at + 8, 1);
}
